#include "ShrubberyCreationForm.hpp"

/******************* CONSTRUCTORS ********************/

ShrubberyCreationForm::ShrubberyCreationForm(void)
	: AForm("Nameless", 145, 137), _target("Nameless") {}

ShrubberyCreationForm::ShrubberyCreationForm(const scf &other)
	: AForm(other.getName(), 145, 137), _target(other.getTarget()) {}

ShrubberyCreationForm::ShrubberyCreationForm(std::string name, std::string target)
	: AForm(name, 145, 137), _target(target) {}

/********************* OPERATORS ********************/

scf	&ShrubberyCreationForm::operator=(const scf &other)
{
	if (this != &other)
		this->_target = other.getTarget();
	return (*this);
}

/******************* DESTRUCTROR ********************/

ShrubberyCreationForm::~ShrubberyCreationForm(void) {}

/********************* GETTER ***********************/

std::string	ShrubberyCreationForm::getTarget(void) const {return (_target);}

/********************* EXECUTE **********************/

